from pathlib import Path
from collections import Counter
import json,re,hashlib,subprocess,sys,datetime,urllib.parse
root=Path.cwd();p=root/'tasks/ui-test-coverage-20261022';e=p/'evidence';out=e/'document-checks.json'
out.write_text('{}\n') if not out.exists() else None
errors=[];link_count=0
catalog=(p/'test-cases.md').read_text();inv=json.loads((e/'case-inventory.json').read_text());source=json.loads((e/'source-manifest.json').read_text())
ids=re.findall(r'^#### ([A-Z][A-Z0-9-]+)\s*$',catalog,re.M)
if len(ids)!=len(set(ids)):errors.append('Duplicate case headings')
if ids!=[c['id'] for c in inv['cases']]:errors.append('Case headings do not match inventory order')
if len(ids)!=inv['total']:errors.append('Inventory total differs from catalog')
blocks=re.findall(r'```gherkin\n(.*?)\n```',catalog,re.S)
if len(blocks)!=len(ids):errors.append('Scenario count differs from case count')
for cid,b in zip(ids,blocks):
 if not all(re.search(r'^\s*'+k+r'\s+\S',b,re.M) for k in ['Given','When','Then']):errors.append(cid+' lacks complete Gherkin')
 if '@'+cid not in b:errors.append(cid+' lacks stable tag')
for c in inv['cases']:
 if c['status']!='NOT_RUN' or c['actual_result'] is not None or c['execution_evidence'] is not None:errors.append(c['id']+' has an unsupported result')
 if c['assertion_count']<1 or not c['source_ids']:errors.append(c['id']+' lacks assertions or sources')
for key,field in [('by_category','category'),('by_basis','basis'),('by_priority','priority'),('by_status','status')]:
 if dict(Counter(c[field] for c in inv['cases']))!=inv[key]:errors.append(key+' count mismatch')
for s in source['sources']:
 f=root/s['path']
 if hashlib.sha256(f.read_bytes()).hexdigest()!=s['sha256']:errors.append('Source hash mismatch: '+s['path'])
for s in source.get('retained_knowledge_source_identities',[]):
 if hashlib.sha256((root/s['path']).read_bytes()).hexdigest()!=s['sha256']:errors.append('Knowledge identity hash mismatch: '+s['path'])
for f in p.rglob('*.md'):
 for m in re.finditer(r'(?<!!)\[[^\]]*\]\((<[^>]+>|[^)\n]+)\)',f.read_text()):
  raw=m[1].strip('<>').split(' "')[0]
  if re.match(r'^[a-z]+://',raw):continue
  t,_,anchor=urllib.parse.unquote(raw).partition('#');q=(f.parent/t).resolve() if t else f.resolve();link_count+=1
  if not q.is_file():errors.append(str(f.relative_to(root))+': missing '+raw);continue
  if anchor:
   text=q.read_text(errors='replace')
   if re.fullmatch(r'L\d+(?:-L?\d+)?',anchor):
    if int(re.search(r'\d+',anchor)[0])>len(text.splitlines()):errors.append('Invalid line locator: '+raw)
   elif q.suffix=='.md':
    heads=re.findall(r'^#{1,6}\s+(.+?)\s*#*$',text,re.M)
    anchors=[re.sub(r'[^\w\- ]','',h.replace('`','').lower()).replace(' ','-') for h in heads]+re.findall(r'<a\s+id="([^"]+)"',text)
    if anchor not in anchors:errors.append('Missing anchor: '+raw)
args=['.venv/bin/ai-sdlc','lint',str(p/'intake.md'),str(p/'test-cases.md')];r=subprocess.run(args,capture_output=True,text=True)
try:lint=json.loads(r.stdout)
except Exception:lint={'stdout':r.stdout,'stderr':r.stderr};errors.append('Lint returned invalid output')
if r.returncode:errors.append('Artifact lint failed')
# Diff whitespace checks cover only the completed task after staging.
checks={'status':'PASSED' if not errors else 'FAILED','run_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'environment':{'python':sys.version,'workspace_baseline':'8dd076eac24c1b18b2f44245b3220ebcaf8537e3'},'command':args,'exit_code':r.returncode,'artifact_lint':lint,'catalog_checks':{'case_count':len(ids),'gherkin_scenario_count':len(blocks),'unique_case_ids':len(set(ids)),'minimum_assertions_per_case':min(c['assertion_count'] for c in inv['cases']),'resolved_local_links':link_count,'checked_source_hashes':len(source['sources']),'checked_retained_knowledge_identities':len(source.get('retained_knowledge_source_identities',[])),'all_business_cases':'NOT_RUN','errors':errors},'document_hashes':{str(f.relative_to(p)):hashlib.sha256(f.read_bytes()).hexdigest() for f in p.rglob('*.md')},'validation_script':{'command':['python3','/tmp/check_ui_catalog.py'],'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'source':Path(__file__).read_text()},'limitations':['Document validation does not execute business test cases.','Lint warnings preserve unknown owners, pending business review, unresolved policies, and pending ASD review.','Link and source-hash checks do not authenticate source authority.','Automated checks do not check the complete approved ASD dictionary or grammar rules.']}
out.write_text(json.dumps(checks,indent=2)+'\n')
print(json.dumps({'status':checks['status'],'case_count':len(ids),'source_hashes':len(source['sources']),'links':link_count,'lint_warnings':len(lint.get('findings',[])),'errors':errors},indent=2))
raise SystemExit(bool(errors))
